mapper.select:
SELECT DISTINCT w.resource_level_id
FROM reservation_work_shift w
INNER JOIN reservation_shift_type t ON w.shift_type_id = t.type_id
WHERE w.company_id = #{companyId}
AND w.shop_id = #{shopId}
AND w.work_date = #{workDate}
AND w.resource_level_id IN
#{id}
AND (w.shift_type_id IS NULL OR CAST(w.shift_type_id AS SIGNED) != -1)
AND NOT (
	UNIX_TIMESTAMP(CONCAT(DATE(FROM_UNIXTIME(UNIX_TIMESTAMP())), ' ', t.begin_time)) >
	UNIX_TIMESTAMP(CONCAT(DATE(FROM_UNIXTIME(UNIX_TIMESTAMP())), ' ', #{beginTime}))
	OR UNIX_TIMESTAMP(CONCAT(DATE(FROM_UNIXTIME(UNIX_TIMESTAMP())), ' ', t.end_time)) <=
	UNIX_TIMESTAMP(CONCAT(DATE(FROM_UNIXTIME(UNIX_TIMESTAMP())), ' ', #{beginTime}))
)
